Here's a modern MSTest test class for `DataFetcher`:

```csharp
[TestClass]
public sealed class DataFetcherTests
{
    private MockHttpMessageHandler _handler = null!;
    private DataFetcher _sut = null!;

    [TestInitialize]
    public void Setup()
    {
        _handler = new MockHttpMessageHandler();
        _sut = new DataFetcher(new HttpClient(_handler));
    }

    // Async tests return Task — MSTest awaits them natively
    [TestMethod]
    public async Task FetchAsync_ReturnsContent_OnSuccess()
    {
        _handler.ResponseContent = "hello";
        _handler.StatusCode = HttpStatusCode.OK;

        var result = await _sut.FetchAsync("https://example.com");

        Assert.AreEqual("hello", result);
    }

    // Use [Timeout] to fail-fast if the test hangs (milliseconds)
    [TestMethod]
    [Timeout(3000)]
    public async Task FetchAsync_ThrowsOnFailureStatusCode()
    {
        _handler.StatusCode = HttpStatusCode.InternalServerError;

        await Assert.ThrowsExceptionAsync<HttpRequestException>(
            () => _sut.FetchAsync("https://example.com"));
    }

    // Verify cancellation is respected
    [TestMethod]
    public async Task FetchAsync_ThrowsWhenCancelled()
    {
        using var cts = new CancellationTokenSource();
        cts.Cancel(); // pre-cancel

        await Assert.ThrowsExceptionAsync<TaskCanceledException>(
            () => _sut.FetchAsync("https://example.com", cts.Token));
    }

    // Minimal mock handler — avoids external mocking libraries
    private sealed class MockHttpMessageHandler : HttpMessageHandler
    {
        public HttpStatusCode StatusCode { get; set; } = HttpStatusCode.OK;
        public string ResponseContent { get; set; } = string.Empty;

        protected override Task<HttpResponseMessage> SendAsync(
            HttpRequestMessage request, CancellationToken cancellationToken)
        {
            cancellationToken.ThrowIfCancellationRequested();

            return Task.FromResult(new HttpResponseMessage(StatusCode)
            {
                Content = new StringContent(ResponseContent)
            });
        }
    }
}
```

**Key patterns used:**

- **`async Task` test methods** — MSTest awaits them directly; no need for `.Result` or `.GetAwaiter()`.
- **`[Timeout(ms)]`** — guards against hangs in async tests. Apply to individual tests or via `[AssemblyInitialize]`.
- **`CancellationToken` forwarding** — test that the token actually reaches `HttpClient` by pre-cancelling a `CancellationTokenSource`.
- **Custom `HttpMessageHandler`** — lets you control responses without hitting the network or pulling in a mocking framework. `HttpClient` delegates to `SendAsync`, so this is the natural seam.
- **`Assert.ThrowsExceptionAsync<T>`** — the async counterpart of `ThrowsException`; properly awaits the delegate.
